23	template <typename xType, typename wType, typename biasType, typename scaleType, typename yType>
24	class QuantBatchMatmulV4Pergroup : public QuantBatchMatmulV4Common {
25	public:
26	    __aicore__ inline QuantBatchMatmulV4Pergroup(){};
27	    __aicore__ inline void Init(GM_ADDR x1, GM_ADDR x2, GM_ADDR bias, GM_ADDR x1_scale, GM_ADDR x2_scale,
28	                                GM_ADDR y_scale, GM_ADDR x1_offset, GM_ADDR x2_offset, GM_ADDR y_offset, GM_ADDR y,
29	                                GM_ADDR workspace, const QuantBatchMatmulV3TilingData* tilingData, TPipe* tPipe)
30	    {
31	        commonInit(tPipe, &(tilingData->matmulTiling));
32	        groupSizeK_ = tilingData->params.groupSizeK;
33	
34	        x1Global_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t*>(x1));
35	        x2Global_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t*>(x2));
36	        biasGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ biasType*>(bias));
37	        mmOutGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(workspace));
38	        x1ScaleGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ scaleType*>(x1_scale));
39	        x2ScaleGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ scaleType*>(x2_scale));
40	        x2OffsetGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ half*>(x2_offset));
41	        yGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ yType*>(y));
42	
43	        ubCalcM_ = tilingData->params.ubCalcM;
44	        ubCalcN_ = tilingData->params.ubCalcN;
45	        maxAivM_ = CeilDiv(baseM_, VECCORE_NUM);
46	
47	        block_.Init(tilingData);
48	        update_.template Init<FORMAT_X1, FORMAT_X2, false, true>(&tilingData->matmulTiling, block_.params_);
49	        nKgroups_ = CeilDiv(block_.matmulTilingData_->Ka, groupSizeK_);
50	        mmObj_.SetSubBlockIdx(0);
51	        mmObj_.Init(&(tilingData->matmulTiling), pipe_);
52	        mmObj_.SetOrgShape(baseM_, baseN_, block_.matmulTilingData_->Ka);
53	        InitLocalBuffers();
54	    };
55	
56	    __aicore__ inline void Process()
57	    {
58	        if (blockIdx_ >= usedCoreNum_) {
59	            return;
60	        }
61	        if ASCEND_IS_AIV {
62	            SetFlag<HardEvent::MTE3_V>(EVENT_ID7);
63	            CrossCoreSetFlag<2, PIPE_MTE2>(V2C_PING_FLAG);
64	            CrossCoreSetFlag<2, PIPE_MTE2>(V2C_PONG_FLAG);
65	        }
66	        // 首块计算，兼容无L2cache切分场景，减少scalar计算
67	        // 反向flag
68	        if ASCEND_IS_AIC {
69	            initEventID();
70	            eAL1_12_ = eAL1Ping12_;
71	            eAL1_21_ = eAL1Ping21_;
72	            eBL1_12_ = eBL1Ping12_;
73	            eBL1_21_ = eBL1Ping21_;
74	            SetFlag<HardEvent::MTE1_MTE2>(eAL1Ping12_);
75	            SetFlag<HardEvent::MTE1_MTE2>(eAL1Pong12_);
76	            SetFlag<HardEvent::MTE1_MTE2>(eBL1Ping12_);
77	            SetFlag<HardEvent::MTE1_MTE2>(eBL1Pong12_);
78	        }
79	
80	        bool reverse = true;
81	        block_.InitFirstTileBlockIndex();
82	        OneTileCompute(0, 0);
83	
84	        for (uint64_t mTileIndex = 0; mTileIndex < block_.params_.mTileCntL2; mTileIndex++) {
85	            reverse = !reverse;
86	            for (uint64_t nTileIndexTemp = 0; nTileIndexTemp < block_.params_.nTileCntL2; nTileIndexTemp++) {
87	                uint64_t nTileIndex = reverse ? (block_.params_.nTileCntL2 - nTileIndexTemp - 1) : nTileIndexTemp;
88	                if (mTileIndex > 0 || nTileIndex > 0) { // 跳过首块
89	                    block_.UpdateBlockCnt(mTileIndex, nTileIndex);
90	                    block_.InitBlockIndex();
91	                    OneTileCompute(mTileIndex, nTileIndex);
92	                }
93	            }
94	        }
95	
96	        // 反向flag
97	        if ASCEND_IS_AIC {
98	            WaitFlag<HardEvent::MTE1_MTE2>(eAL1Ping12_);
99	            WaitFlag<HardEvent::MTE1_MTE2>(eAL1Pong12_);
100	            WaitFlag<HardEvent::MTE1_MTE2>(eBL1Ping12_);
101	            WaitFlag<HardEvent::MTE1_MTE2>(eBL1Pong12_);
102	            CrossCoreWaitFlag(V2C_PING_FLAG);
103	            CrossCoreWaitFlag(V2C_PONG_FLAG);
104	            mmObj_.End();
105	            releaseEventID();
106	        }
107	        if ASCEND_IS_AIV {
108	            WaitFlag<HardEvent::MTE3_V>(EVENT_ID7);
109	        }
110	    }
111	
112	    __aicore__ inline void InitLocalBuffers()
113	    {
114	        if ASCEND_IS_AIC {
115	            // Note: assume xtype == wtype
116	            pipe_->InitBuffer(L1Buf_, L1_MAX_SIZE_910B);
117	            uint32_t a_size = baseM_ * groupSizeK_ * stepka_;
118	            uint32_t b_size = baseN_ * groupSizeK_ * stepkb_;
119	            aL1Ping_ = L1Buf_.Get<xType>()[0];
120	            aL1Pong_ = aL1Ping_[a_size];
121	            bL1Ping_ = aL1Pong_[a_size];
122	            bL1Pong_ = bL1Ping_[b_size];
123	            aL1_ = aL1Ping_;
124	            bL1_ = bL1Ping_;
125	        }
126	
127	        if ASCEND_IS_AIV {
128	            // mmOutFp32 和 x2scale需要避免bank冲突
129	            // mmOutFp32 和 dequantAccu需要避免bank冲突
130	            pipe_->InitBuffer(ubBuf_, TOTAL_UB_SIZE); // 192KB
131	            uint64_t offset = 0;
132	            dequantAccu = ubBuf_.Get<float>()[0];
133	            dequantOut = ubBuf_.Get<yType>()[0];
134	            offset += maxAivM_ * ubCalcN_;
135	            mmOut = ubBuf_.Get<int32_t>()[offset]; // [ubCalcM_, ubCalcN_]
136	            offset += ubCalcM_ * ubCalcN_;
137	            // 解bank冲突： mmOutFp32 和 dequantAccu 需要隔开256B
138	            // offset += 64;
139	            mmOutFp32 = ubBuf_.Get<float>()[offset];
140	            offset += ubCalcM_ * ubCalcN_;
141	            // ubCalcN_ 32B对齐
142	            X2Scale = ubBuf_.Get<float>()[offset];
143	            offset += ubCalcN_;
144	            bias = ubBuf_.Get<float>()[offset];
145	            offset += ubCalcN_;
146	            X1Scale = ubBuf_.Get<float>()[offset];
147	            offset += CeilAlign(maxAivM_, ALIGN_UNIT_8);
148	            X1BrcbScale = ubBuf_.Get<float>()[offset];
149	            offset += (CeilAlign(maxAivM_, ALIGN_UNIT_8) * ALIGN_UNIT_8);
150	
151	            X1Fp32 = ubBuf_.Get<float>()[offset];
152	            X1INT8 = X1Fp32.ReinterpretCast<int8_t>();
153	            X1INT4 = X1Fp32.ReinterpretCast<int4b_t>();
154	            offset += ubCalcM_ * groupSizeK_;
155	            X1Half = ubBuf_.Get<float>()[offset].ReinterpretCast<half>();
156	            offset += ubCalcM_ * groupSizeK_ >> 1;
157	            X1RowSum = ubBuf_.Get<float>()[offset];
158	            offset += CeilAlign(maxAivM_, 8);
159	            X1BCast = ubBuf_.Get<float>()[offset];
160	            offset += ubCalcM_ * ubCalcN_;
161	            X2Offset = ubBuf_.Get<float>()[offset];
162	            offset += ubCalcN_;
163	            X2OffsetFP16 = ubBuf_.Get<float>()[offset].ReinterpretCast<half>();
164	            offset += ubCalcN_ >> 1;
165	            X1BCastMulX2Offset = ubBuf_.Get<float>()[offset];
166	            offset += ubCalcM_ * ubCalcN_;
167	        }
168	    };
