178	    bool aL1PingFlag_ = true;
179	    bool bL1PingFlag_ = true;
180	    bool wsPingFlag_ = true;
181	    bool ubPingFlag_ = true;
182	    bool x2ScalePingFlag_ = true;
183	
184	    GlobalTensor<int8_t> x1Global_;
185	    GlobalTensor<int8_t> x2Global_;
186	    GlobalTensor<biasType> biasGlobal_;
187	    GlobalTensor<int32_t> mmOutGlobal_;
188	    // GlobalTensor<float16_t> mmOutGlobal_;
189	    GlobalTensor<scaleType> x1ScaleGlobal_;
190	    GlobalTensor<scaleType> x2ScaleGlobal_;
191	    GlobalTensor<half> x2OffsetGlobal_;
192	    GlobalTensor<yType> yGlobal_;
193	    // define pingpong buf
194	    TBuf<TPosition::A1> L1Buf_;
195	    LocalTensor<xType> aL1_;
196	    LocalTensor<wType> bL1_;
197	    LocalTensor<xType> aL1Ping_;
198	    LocalTensor<wType> aL1Pong_;
199	    LocalTensor<xType> bL1Ping_;
200	    LocalTensor<wType> bL1Pong_;
201	
202	    // Vec buffer
203	    // 不切N ubCalcN_ = BaseN
204	    // mmOut, mmOutFp32, dequantOut可共享内存
205	    TBuf<> ubBuf_;
206	    LocalTensor<int32_t> mmOut;     // [ubCalcM_, ubCalcN_]
207	    LocalTensor<float> mmOutFp32;   // [ubCalcM_, ubCalcN_]
208	    LocalTensor<float> dequantAccu; // [AivM_, ubCalcN_]
209	    LocalTensor<yType> dequantOut;  // [AivM_, ubCalcN_]
210	    LocalTensor<float> X1BrcbScale; // [AivM_, 8]
211	    LocalTensor<float> X1Scale;     // [AivM_]
212	    LocalTensor<float> X2Scale;     // [ubCalcN_] // 32B align
213	    LocalTensor<float> bias;        // [ubCalcN_]
214	
215	    LocalTensor<int8_t> X1INT8;            // [ubCalcM_, groupsizeK]
216	    LocalTensor<int4b_t> X1INT4;           // [ubCalcM_, groupsizeK]
217	    LocalTensor<float> X2Offset;           // [ubCalcN_]
218	    LocalTensor<half> X2OffsetFP16;        // [ubCalcN_]
219	    LocalTensor<float> X1Fp32;             // [ubCalcM_, groupsizeK]
220	    LocalTensor<half> X1Half;              // [ubCalcM_, groupsizeK]
221	    LocalTensor<float> X1RowSum;           // [ubCalcM_]
222	    LocalTensor<float> X1BCast;            // [ubCalcM_, ubCalcN_]
223	    LocalTensor<float> X1BCastMulX2Offset; // [ubCalcM_, ubCalcN_]
224	
225	    TEventID eX1Scale_ = EVENT_ID0;
226	    TEventID eX2Scale_ = EVENT_ID1;
227	    TEventID eMmOut_ = EVENT_ID2;
228	    TEventID eX2Offset_ = EVENT_ID3;
229	    TEventID eX1_ = EVENT_ID4;
230	
