233	    // tilingData
234	    using inputX1Type = MatmulType<TPosition::TSCM, CubeFormat::NZ, xType, false>;
235	    using inputX2Type = MatmulType<TPosition::TSCM, CubeFormat::NZ, wType, true>;
236	    using inputBiasType = MatmulType<TPosition::GM, CubeFormat::ND, biasType, false>;
237	    using outputYType = MatmulType<TPosition::GM, CubeFormat::ND, int32_t, false>;
238	    MatmulImpl<inputX1Type, inputX2Type, outputYType, inputBiasType, CFG_MDL> mmObj_;
