240	    __aicore__ inline void CopyInX1Scale(uint32_t curAivM)
241	    {
242	        // X1Scale [AivM_] // 32B align
243	        uint32_t offset = offset_.offsetPertoken + subBlockIdx_ * maxAivM_;
244	        DataCopyPad(X1Scale, x1ScaleGlobal_[offset],
245	                    {/*blk_count*/ 1, /*blk_len*/ uint32_t(curAivM * sizeof(float)), 0, 0, 0}, {false, 0, 0, 0});
246	        SetFlag<HardEvent::MTE2_V>(eX1Scale_);
247	    }
248	
249	    __aicore__ inline void CopyInX2Scale(uint32_t kidx, uint32_t curAivN)
250	    {
251	        // X2Scale; // [ubCalcN_] // 32B align
252	        // x2ScaleGlobal_ [nKgroups_, n]
253	        uint64_t offset = static_cast<uint64_t>(kidx) * block_.matmulTilingData_->N + offset_.offsetScale;
254	        DataCopyPad(X2Scale, x2ScaleGlobal_[offset],
255	                    {/*blk_count*/ 1, /*blk_len*/ uint32_t(curAivN * sizeof(float)), 0, 0, 0}, {false, 0, 0, 0});
256	        SetFlag<HardEvent::MTE2_V>(eX2Scale_);
257	    }
258	
259	    __aicore__ inline void CopyInX2Offset(uint32_t kidx, uint32_t curAivN)
260	    {
261	        // X2Offset; // [ubCalcN_] // 32B align
262	        // x2SOffset_ [nKgroups_, n]
263	        uint64_t offset = static_cast<uint64_t>(kidx) * block_.matmulTilingData_->N + offset_.offsetScale;
264	        DataCopyPad(X2OffsetFP16, x2OffsetGlobal_[offset],
265	                    {/*blk_count*/ 1, /*blk_len*/ uint32_t(curAivN * sizeof(half)), 0, 0, 0}, {false, 0, 0, 0});
266	        SetFlag<HardEvent::MTE2_V>(eX2Offset_);
267	    }
268	
269	    __aicore__ inline void CopyInX1INT8(uint32_t kidx, uint32_t midx, uint32_t curAivM)
270	    {
271	        // CopyIn X1
272	        // Copy INT4 as INT8
273	        // [m, k]
274	        uint64_t X1_offset = static_cast<uint64_t>(offset_.offsetA) + static_cast<uint64_t>(kidx) * groupSizeK_ +
275	                             (static_cast<uint64_t>(subBlockIdx_) * maxAivM_ + static_cast<uint64_t>(ubCalcM_) * midx) *
276	                                 block_.matmulTilingData_->Ka;
277	        uint16_t blockCount = curAivM;
278	        uint16_t blockLen = groupSizeK_ / 2 / DATA_BLOCK_LEN;
279	        uint16_t srcGap = (block_.matmulTilingData_->Ka - groupSizeK_) / 2 / DATA_BLOCK_LEN;
280	        uint16_t dstGap = 0;
281	        DataCopy(X1INT8, x1Global_[X1_offset >> 1], {blockCount, blockLen, srcGap, dstGap});
282	        SetFlag<HardEvent::MTE2_V>(eX1_);
283	        WaitFlag<HardEvent::MTE2_V>(eX1_);
284	    }
285	
286	    __aicore__ inline void X2OffsetProcess(uint32_t curAivM, uint32_t curAivN, uint32_t kidx, uint32_t midx)
287	    {
288	        CopyInX1INT8(kidx, midx, curAivM);
289	        uint8_t dstRepeatStride = 8UL;
290	        uint8_t srcRepeatStride1 = 2UL;
291	        Cast<half, int4b_t, false>(X1Half, X1INT4, RoundMode::CAST_NONE, /*mask*/ 0UL,
292	                                   /*repeatTime*/ srcRepeatStride1 * curAivM,
293	                                   {1, 1, dstRepeatStride, srcRepeatStride1});
294	        PipeBarrier<PIPE_V>();
295	        uint8_t srcRepeatStride2 = 4UL;
296	        Cast<float, half, false>(X1Fp32, X1Half, RoundMode::CAST_NONE, /*mask*/ 0UL,
297	                                 /*repeatTime*/ srcRepeatStride2 * curAivM, {1, 1, dstRepeatStride, srcRepeatStride2});
298	        PipeBarrier<PIPE_V>();
299	        // // use X1BCastMulX2Offset as sharedTmpBuffer
300	        // // 文档未说明此处tmpbuffer会用多大，但已X1BCastMulX2Offset为起点的ub空间不会踩踏前面有用的空间
301	        // // 后面再用到X1BCastMulX2Offset时通过pipe_V隔离
302	        uint32_t shape[] = {curAivM, groupSizeK_};
303	        ReduceSum<float, Pattern::Reduce::AR, false>(
304	            X1RowSum, X1Fp32, /*tmp*/ X1BCastMulX2Offset.ReinterpretCast<uint8_t>(), shape, true);
305	        PipeBarrier<PIPE_V>();
306	        uint32_t dstShape_[] = {curAivM, curAivN};
307	        uint32_t srcShape_[] = {curAivM, 1};
308	        LocalTensor<uint8_t> sharedTmpBuffer = X1BCastMulX2Offset.ReinterpretCast<uint8_t>();
309	        constexpr int32_t dim = 2;
310	        constexpr int32_t axis = 1;
311	        Broadcast<float, dim, axis, false>(X1BCast, X1RowSum, dstShape_, srcShape_, sharedTmpBuffer);
312	        PipeBarrier<PIPE_V>();
313	        int32_t resN = curAivN;
314	        uint8_t repeatStride = CeilDiv(curAivN, ALIGN_UNIT_8);
315	        uint32_t repeatTime = 4;
316	        if (midx == 0) {
317	            WaitFlag<HardEvent::MTE2_V>(eX2Offset_);
318	            Cast<float, half, false>(X2Offset, X2OffsetFP16, RoundMode::CAST_NONE, /*mask*/ 0UL,
319	                                     /*repeatTime*/ repeatTime, {1, 1, dstRepeatStride, srcRepeatStride2});
320	            PipeBarrier<PIPE_V>();
321	        }
322	        while (resN >= NUM_ELEMENTS_PER_ITER) {
323	            Mul<float, false>(X1BCastMulX2Offset[curAivN - resN], X2Offset[curAivN - resN], X1BCast[curAivN - resN],
324	                              0UL, curAivM, {1, 1, 1, repeatStride, 0, repeatStride});
325	            resN = resN - NUM_ELEMENTS_PER_ITER;
326	        }
327	        if (resN > 0) {
328	            Mul<float, true>(X1BCastMulX2Offset[curAivN - resN], X2Offset[curAivN - resN], X1BCast[curAivN - resN],
329	                             resN, curAivM, {1, 1, 1, repeatStride, 0, repeatStride});
330	        }
331	        PipeBarrier<PIPE_V>();
332	    }
333	
334	    __aicore__ inline void DequantAndAccu(uint32_t curAivM, uint32_t curAivN, uint32_t kidx, uint32_t midx)
335	    {
336	        WaitFlag<HardEvent::MTE2_V>(eMmOut_);
337	        uint8_t dstRepeatStride = 8UL;
338	        uint8_t srcRepeatStride = 8UL;
339	
340	        Cast<float, int32_t, false>(mmOutFp32, mmOut, RoundMode::CAST_NONE, /*mask*/ 0UL,
341	                                    /*repeatTime*/ FOLD4 * curAivM, {1, 1, dstRepeatStride, srcRepeatStride});
342	        PipeBarrier<PIPE_V>();
343	        X2OffsetProcess(curAivM, curAivN, kidx, midx);
344	        uint8_t src0RepeatStride = 8UL;
345	        uint8_t src1RepeatStride = 8UL;
346	        Sub<float, false>(mmOutFp32, mmOutFp32, X1BCastMulX2Offset, 0UL, FOLD4 * curAivM,
347	                          {1, 1, 1, dstRepeatStride, src0RepeatStride, src1RepeatStride});
348	        PipeBarrier<PIPE_V>();
349	        int32_t resN = curAivN;
350	        uint8_t repeatStride = CeilDiv(curAivN, ALIGN_UNIT_8);
351	
352	        if (midx == 0) {
353	            WaitFlag<HardEvent::MTE2_V>(eX2Scale_);
354	        }
355	        while (resN >= NUM_ELEMENTS_PER_ITER) {
356	            Mul<float, false>(mmOutFp32[curAivN - resN], X2Scale[curAivN - resN], mmOutFp32[curAivN - resN], 0UL,
357	                              curAivM, {1, 1, 1, repeatStride, 0, repeatStride});
358	            resN = resN - NUM_ELEMENTS_PER_ITER;
359	        }
360	        if (resN > 0) {
361	            Mul<float, true>(mmOutFp32[curAivN - resN], X2Scale[curAivN - resN], mmOutFp32[curAivN - resN], resN,
362	                             curAivM, {1, 1, 1, repeatStride, 0, repeatStride});
363	        }
364	        PipeBarrier<PIPE_V>();
365	        uint32_t moffset = ubCalcM_ * midx * curAivN;
366	        Add<float, false>(dequantAccu[moffset], mmOutFp32, dequantAccu[moffset], 0UL, FOLD4 * curAivM,
367	                          {1, 1, 1, dstRepeatStride, src0RepeatStride, src1RepeatStride});
368	        PipeBarrier<PIPE_ALL>();
369	    }
370	
371	    __aicore__ inline void CopyInMMOut(uint32_t midx, uint32_t realM, uint32_t CurAicN)
372	    {
373	        GlobalTensor<int32_t> src = mmOutGlobal_[wsPingFlag_ ? offsetWorkspaceC_ : offsetWorkspacePong_];
374	        uint32_t moffset = (subBlockIdx_ * maxAivM_ + ubCalcM_ * midx) * CurAicN;
375	        src = src[moffset];
376	        DataCopy(mmOut, src, realM * CurAicN);
377	        SetFlag<HardEvent::MTE2_V>(eMmOut_);
378	    }
379	
380	    __aicore__ inline void CastCopyOut(uint32_t curAivM, uint32_t curAivN)
381	    {
382	        WaitFlag<HardEvent::MTE2_V>(eX1Scale_);
383	        uint8_t dstRepeatStride = 8UL;
384	        Brcb(X1BrcbScale, X1Scale, CeilDiv(curAivM, ALIGN_UNIT_8), {1, dstRepeatStride});
385	        PipeBarrier<PIPE_V>();
386	        int32_t resN = curAivN;
387	        uint8_t repeatStride = CeilDiv(curAivN, ALIGN_UNIT_8);
388	        while (resN >= NUM_ELEMENTS_PER_ITER) {
389	            Mul(dequantAccu[curAivN - resN], X1BrcbScale, dequantAccu[curAivN - resN], NUM_ELEMENTS_PER_ITER, curAivM,
390	                {1, 0, 1, repeatStride, 1, repeatStride});
391	            resN = resN - NUM_ELEMENTS_PER_ITER;
392	        }
393	        if (resN > 0) {
394	            Mul(dequantAccu[curAivN - resN], X1BrcbScale, dequantAccu[curAivN - resN], resN, curAivM,
395	                {1, 0, 1, repeatStride, 1, repeatStride});
396	        }
397	        PipeBarrier<PIPE_V>();
398	        Cast(dequantOut, dequantAccu, RoundMode::CAST_RINT, curAivM * curAivN);
399	        SetFlag<HardEvent::V_MTE3>(EVENT_ID7);
400	        uint64_t stride = DATA_BLOCK / sizeof(yType);
401	        DataCopyParams copyParams{uint16_t(curAivM), uint16_t(curAivN / stride), // * sizeof(bfloat16) / 32B
402	                                  0, uint16_t((block_.matmulTilingData_->N - curAivN) / stride)};
403	        uint64_t offset = offset_.offsetC;
404	        offset += subBlockIdx_ * maxAivM_ * block_.matmulTilingData_->N;
405	        WaitFlag<HardEvent::V_MTE3>(EVENT_ID7);
406	        DataCopy(yGlobal_[offset], dequantOut, copyParams);
407	        SetFlag<HardEvent::MTE3_V>(EVENT_ID7);
408	        return;
409	    }
410	
411	    __aicore__ inline void shiftFlagAL1()
412	    {
413	        aL1PingFlag_ = !aL1PingFlag_;
414	        aL1_ = aL1PingFlag_ ? aL1Ping_ : aL1Pong_;
415	        eAL1_12_ = aL1PingFlag_ ? eAL1Ping12_ : eAL1Pong12_;
416	        eAL1_21_ = aL1PingFlag_ ? eAL1Ping21_ : eAL1Pong21_;
417	    }
418	
419	    __aicore__ inline void shiftFlagBL1()
420	    {
421	        bL1PingFlag_ = !bL1PingFlag_;
422	        bL1_ = bL1PingFlag_ ? bL1Ping_ : bL1Pong_;
423	        eBL1_12_ = bL1PingFlag_ ? eBL1Ping12_ : eBL1Pong12_;
424	        eBL1_21_ = bL1PingFlag_ ? eBL1Ping21_ : eBL1Pong21_;
425	    }
426	
427	    __aicore__ inline void CubeProcess(uint32_t CurAicM, uint32_t CurAicN, uint32_t kidx)
428	    {
429	        if (kidx % stepka_ == 0) {
430	            // INT4也要按照INT8搬
431	            WaitFlag<HardEvent::MTE1_MTE2>(eAL1_12_);
432	            Nd2NzParams nd2nzParamsA;
433	            nd2nzParamsA.ndNum = 1;
434	            nd2nzParamsA.srcDValue = block_.matmulTilingData_->Ka >> 1;
435	            nd2nzParamsA.srcNdMatrixStride = 0;
436	            nd2nzParamsA.dstNzNStride = 1;
437	            nd2nzParamsA.dstNzMatrixStride = 0;
438	            nd2nzParamsA.dstNzC0Stride = CeilAlign(CurAicM, ALIGN_UNIT_16);
439	            nd2nzParamsA.nValue = CurAicM;
440	            nd2nzParamsA.dValue = (stepka_ * groupSizeK_) >> 1;
441	            DataCopy(aL1_.template ReinterpretCast<int8_t>(), x1Global_[(offset_.offsetA + kidx * groupSizeK_) >> 1],
442	                     nd2nzParamsA);
443	            SetFlag<HardEvent::MTE2_MTE1>(eAL1_21_);
444	            WaitFlag<HardEvent::MTE2_MTE1>(eAL1_21_);
445	        }
446	        if (kidx % stepkb_ == 0) {
447	            WaitFlag<HardEvent::MTE1_MTE2>(eBL1_12_);
448	            Nd2NzParams nd2nzParamsB;
449	            nd2nzParamsB.ndNum = 1;
450	            nd2nzParamsB.srcDValue = block_.matmulTilingData_->Ka >> 1;
451	            nd2nzParamsB.srcNdMatrixStride = 0;
452	            nd2nzParamsB.dstNzNStride = 1;
453	            nd2nzParamsB.dstNzMatrixStride = 0;
454	            nd2nzParamsB.dstNzC0Stride = CeilAlign(CurAicN, ALIGN_UNIT_16);
455	            nd2nzParamsB.nValue = CurAicN;
456	            nd2nzParamsB.dValue = (stepkb_ * groupSizeK_) >> 1;
457	            DataCopy(bL1_.template ReinterpretCast<int8_t>(), x2Global_[(offset_.offsetB + kidx * groupSizeK_) >> 1],
458	                     nd2nzParamsB);
459	            SetFlag<HardEvent::MTE2_MTE1>(eBL1_21_);
460	            WaitFlag<HardEvent::MTE2_MTE1>(eBL1_21_);
461	        }
462	
463	        mmObj_.SetTensorA(aL1_[kidx % stepka_ * groupSizeK_ * CeilAlign(CurAicM, ALIGN_UNIT_16)], /*transa*/ false);
464	        mmObj_.SetTensorB(bL1_[kidx % stepkb_ * groupSizeK_ * baseN_], /*transb*/ true);
465	
466	        mmObj_.SetSingleShape(block_.params_.singleCoreM, block_.params_.singleCoreN, groupSizeK_);
467	        mmObj_.Iterate(false);
468	        if ((kidx + 1) % stepka_ == 0) {
469	            SetFlag<HardEvent::MTE1_MTE2>(eAL1_12_);
470	            shiftFlagAL1();
471	        }
472	        if ((kidx + 1) % stepkb_ == 0) {
473	            SetFlag<HardEvent::MTE1_MTE2>(eBL1_12_);
474	            shiftFlagBL1();
475	        }
476	        CrossCoreWaitFlag(V2C_PING_FLAG | wsPingFlag_);
477	        mmObj_.GetTensorC(mmOutGlobal_[wsPingFlag_ ? offsetWorkspaceC_ : offsetWorkspacePong_], 0, true);
478	        CrossCoreSetFlag<CV_SYNC_FLAG, PIPE_FIX>(C2V_PING_FLAG | wsPingFlag_);
479	    }
480	
481	    __aicore__ inline void BasicMMDequantCompute(uint32_t CurAicM, uint32_t CurAicN, uint32_t kidx, int32_t CurAivM)
482	    {
483	        if ASCEND_IS_AIC {
484	            CubeProcess(CurAicM, CurAicN, kidx);
485	        }
486	        if ASCEND_IS_AIV {
487	            if (CurAivM > 0) {
488	                uint64_t mloop = CeilDiv(CurAivM, ubCalcM_);
489	                uint32_t tailM = CurAivM - ubCalcM_ * (mloop - 1);
490	                for (uint32_t mUbLoopIdx = 0; mUbLoopIdx < mloop; ++mUbLoopIdx) {
491	                    if (mUbLoopIdx == 0) {
492	                        CrossCoreWaitFlag(C2V_PING_FLAG | wsPingFlag_);
493	                    }
494	                    CopyInMMOut(mUbLoopIdx, mloop == 1 ? tailM : ubCalcM_, CurAicN);
495	                    if (mUbLoopIdx == mloop - 1) {
496	                        CrossCoreSetFlag<2, PIPE_MTE2>(V2C_PING_FLAG | wsPingFlag_);
497	                    }
498	                    DequantAndAccu(mUbLoopIdx == mloop - 1 ? tailM : ubCalcM_, CurAicN, kidx, mUbLoopIdx);
499	                }
500	            } else {
501	                CrossCoreWaitFlag(C2V_PING_FLAG | wsPingFlag_);
502	                CrossCoreSetFlag<2, PIPE_MTE2>(V2C_PING_FLAG | wsPingFlag_);
503	            }
504	        }
505	        wsPingFlag_ = !wsPingFlag_;
506	    }
507	
508	    __aicore__ inline uint32_t GetCurAivM()
509	    { // 计算m轴尾块
510	        uint32_t curAivM = maxAivM_;
511	        if (block_.params_.singleCoreM != baseM_) {
512	            if (subBlockIdx_ == 0) {
513	                curAivM = block_.params_.singleCoreM > curAivM ? curAivM : block_.params_.singleCoreM;
514	            } else {
515	                curAivM = block_.params_.singleCoreM > curAivM ? block_.params_.singleCoreM - curAivM : 0UL;
516	            }
517	        }
518	        return curAivM;
519	    }
520	
521	    __aicore__ inline void OneTileCompute(uint64_t mTileIndex, uint64_t nTileIndex)
522	    {
523	        for (uint64_t j = 0; j < block_.realRound_; j++) {
524	            // 更新此次基本块的大小和输入输出地址
525	            update_.template UpdateBlockParamsAndCalcGmOffset<FORMAT_X1, FORMAT_X2, /*atrans*/ false, /*btrans*/ true>(
526	                block_.params_, offset_, mTileIndex, nTileIndex);
527	            uint32_t aivM = GetCurAivM();
528	            if ASCEND_IS_AIV {
529	                if (aivM > 0) {
530	                    WaitFlag<HardEvent::MTE3_V>(EVENT_ID7);
531	                    Duplicate(dequantAccu, float(0), aivM * ubCalcN_);
532	                    PipeBarrier<PIPE_V>();
533	                    CopyInX1Scale(aivM);
534	                }
535	            }
536	            for (uint64_t k = 0; k < nKgroups_; k++) {
537	                if (aivM > 0) {
538	                    CopyInX2Scale(k, block_.params_.singleCoreN);
539	                    CopyInX2Offset(k, block_.params_.singleCoreN);
540	                }
541	                BasicMMDequantCompute(block_.params_.singleCoreM, block_.params_.singleCoreN, k, aivM);
542	            }
543	            block_.UpdateBlockIndex();
544	            if ASCEND_IS_AIV {
545	                if (aivM > 0) {
546	                    CastCopyOut(aivM, block_.params_.singleCoreN);
547	                }
548	            }
549	        }
550	    }
551	};
552	
553	} // namespace AscendC
554	#endif
555

